const root=path.resolve(process.argv[2]||path.resolve(__dirname,'..','..')),out=path.resolve(process.argv[3]||require('node:os').tmpdir()),session=process.argv[4]||'history-qa-'+process.pid,url=process.argv[5]||'http://127.0.0.1:5586/index-3d.html',G=require(path.join(root,'game.js'));
