 importFile('research-history-ui-before-history2018.json');research();const recordedBefore=card('history2017');lab();run('click','#mitigate');research();const recordedAfter=card('history2017'),newPlan=card('history2018');assert(recordedBefore===recordedAfter&&recordedAfter.includes('Recorded entry: 131 funding')&&newPlan.includes('New entry: 59 funding'),'Captured historical quote changed with future mitigation');observations.push({kind:'captured-quote',recordedBefore,recordedAfter,newPlan});
 lab();run('focus','#service');run('press','Home');const entryBefore=state();assert(entryBefore.paused&&!entryBefore.mitigate,'Expected paused ordinary plan missing');run('click','#pause-toggle');research();run('click','#archive-list [data-study="history2018"]');const entered=state();assert(entered.job==='history2018'&&Math.abs(entryBefore.funds-entered.funds-59)<15,'Study entry fee missing');
